def priority(p: tuple, n: int) -> float:
    # 初始种群基线：基于坐标加权与模特征
    score = 0.0
    for idx, val in enumerate(p):
        if val == 1:
            score += 2.0
        elif val == 2:
            score += 1.5
        else:
            score -= 0.5
        score += idx * 0.1
    return float(score)
